import json

def exists(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.exists', json.dumps({'path': path}))['returnValue']

def duplicate(source, destination):
    if exists(destination):
        return 'existing'
    ok = execute_tool('editor_toolset.toolsets.asset.AssetTools.duplicate', json.dumps({'path': source, 'new_path': destination}))['returnValue']
    if not ok:
        raise RuntimeError('Failed to duplicate ' + source + ' to ' + destination)
    return 'created'

def save(paths):
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']:
        raise RuntimeError('Failed to save Week 3 weapon assets')

def run():
    copies = {
        '/ExtractionOps/Weapons/Rifle/ID_ExtractionRifle': '/ShooterCore/Weapons/Rifle/ID_Rifle',
        '/ExtractionOps/Weapons/Rifle/WID_ExtractionRifle': '/ShooterCore/Weapons/Rifle/WID_Rifle',
        '/ExtractionOps/Weapons/Rifle/B_WeaponInstance_ExtractionRifle': '/ShooterCore/Weapons/Rifle/B_WeaponInstance_Rifle',
        '/ExtractionOps/Weapons/Rifle/AbilitySet_ExtractionRifle': '/ShooterCore/Weapons/Rifle/AbilitySet_ShooterRifle',
        '/ExtractionOps/Weapons/Rifle/GA_Weapon_Fire_ExtractionRifle': '/ShooterCore/Weapons/Rifle/GA_Weapon_Fire_Rifle_Auto',
        '/ExtractionOps/Weapons/Rifle/GA_Weapon_Reload_ExtractionRifle': '/ShooterCore/Weapons/Rifle/GA_Weapon_Reload_Rifle',
        '/ExtractionOps/Weapons/Rifle/GE_Damage_ExtractionRifle': '/ShooterCore/Weapons/Rifle/GE_Damage_RifleAuto',
        '/ExtractionOps/Weapons/Rifle/B_ExtractionRifle': '/ShooterCore/Weapons/Rifle/B_Rifle',
        '/ExtractionOps/Weapons/Shotgun/ID_ExtractionShotgun': '/ShooterCore/Weapons/Shotgun/ID_Shotgun',
        '/ExtractionOps/Weapons/Shotgun/WID_ExtractionShotgun': '/ShooterCore/Weapons/Shotgun/WID_Shotgun',
        '/ExtractionOps/Weapons/Shotgun/B_WeaponInstance_ExtractionShotgun': '/ShooterCore/Weapons/Shotgun/B_WeaponInstance_Shotgun',
        '/ExtractionOps/Weapons/Shotgun/AbilitySet_ExtractionShotgun': '/ShooterCore/Weapons/Shotgun/AbilitySet_ShooterShotgun',
        '/ExtractionOps/Weapons/Shotgun/GA_Weapon_Fire_ExtractionShotgun': '/ShooterCore/Weapons/Shotgun/GA_Weapon_Fire_Shotgun',
        '/ExtractionOps/Weapons/Shotgun/GA_Weapon_Reload_ExtractionShotgun': '/ShooterCore/Weapons/Shotgun/GA_Weapon_Reload_Shotgun',
        '/ExtractionOps/Weapons/Shotgun/GE_Damage_ExtractionShotgun': '/ShooterCore/Weapons/Shotgun/GE_Damage_Shotgun',
        '/ExtractionOps/Weapons/Shotgun/B_ExtractionShotgun': '/ShooterCore/Weapons/Shotgun/B_Shotgun'
    }
    results = {}
    for destination, source in copies.items():
        results[destination] = duplicate(source, destination)
    save(list(copies.keys()))
    return {'assets': results, 'saved': True}
